package com.sneha.snehamart.controller;
import com.google.gson.*;import com.sneha.snehamart.dao.JdbcDAO;import com.sneha.snehamart.service.ChatProvider;import com.sneha.snehamart.service.MockChatProvider;import com.sneha.snehamart.service.OrderService;import com.zaxxer.hikari.HikariDataSource;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.math.BigDecimal;import java.sql.*;import java.util.*;import java.util.regex.*;import org.mindrot.jbcrypt.BCrypt;
/** Front controller for SnehaMart's versioned JSON API. */
@WebServlet(urlPatterns="/api/v1/*") public final class ApiServlet extends HttpServlet {
 private static final Gson G=new Gson();private HikariDataSource ds;private JdbcDAO dao;private ChatProvider chatProvider;private OrderService orderService;public void init(){ds=(HikariDataSource)getServletContext().getAttribute("dataSource");dao=new JdbcDAO(ds);orderService=new OrderService(dao);chatProvider=new MockChatProvider();}
 private Map<String,Object> body(HttpServletRequest r)throws IOException{try{return G.fromJson(r.getReader(),Map.class);}catch(RuntimeException e){throw new Bad("Invalid JSON body");}}
 private void send(HttpServletResponse r,int status,Object data)throws IOException{r.setStatus(status);r.setContentType("application/json;charset=UTF-8");r.getWriter().write(G.toJson(Map.of("success",status<400,"data",status<400?data:JsonNull.INSTANCE,"error",status<400?JsonNull.INSTANCE:Map.of("code",status==401?"UNAUTHENTICATED":"REQUEST_ERROR","message",String.valueOf(data)))));}
 private Map<String,Object> user(HttpServletRequest r){Object u=r.getSession(false)==null?null:r.getSession(false).getAttribute("user");return u instanceof Map?(Map<String,Object>)u:null;}private Map<String,Object> need(HttpServletRequest r,String...roles){Map<String,Object>u=user(r);if(u==null)throw new Nope();if(roles.length>0&&!Arrays.asList(roles).contains(u.get("role")))throw new Forbidden();return u;}private long uid(HttpServletRequest r){return ((Number)need(r).get("id")).longValue();}private long number(Object x){return x instanceof Number n?n.longValue():Long.parseLong(String.valueOf(x));}private String str(Map<String,Object>b,String k){return b.get(k)==null?"":String.valueOf(b.get(k)).trim();}
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws IOException{String p=q.getPathInfo();try{if(p==null)p="/";if(p.equals("/products")){String cat=q.getParameter("category"),key=q.getParameter("q");String sql="SELECT p.*,COALESCE((SELECT AVG(rating) FROM reviews r WHERE r.product_id=p.id),0) rating, (SELECT COUNT(*) FROM reviews r WHERE r.product_id=p.id) review_count FROM products p WHERE p.active=TRUE";if(cat!=null&&!cat.isBlank())sql+=" AND p.category=?";if(key!=null&&!key.isBlank())sql+=" AND (LOWER(p.name) LIKE ? OR LOWER(p.description) LIKE ?)";sql+=" ORDER BY p.created_at DESC";List<Map<String,Object>> a;if(cat!=null&&!cat.isBlank()&&key!=null&&!key.isBlank())a=dao.query(sql,cat,"%"+key.toLowerCase()+"%","%"+key.toLowerCase()+"%");else if(cat!=null&&!cat.isBlank())a=dao.query(sql,cat);else if(key!=null&&!key.isBlank())a=dao.query(sql,"%"+key.toLowerCase()+"%","%"+key.toLowerCase()+"%");else a=dao.query(sql);send(s,200,a);return;}if(p.matches("/products/[0-9]+")){long id=Long.parseLong(p.substring(10));List<Map<String,Object>>a=dao.query("SELECT * FROM products WHERE id=? AND active=TRUE",id);if(a.isEmpty())throw new Missing();Map<String,Object>x=a.get(0);x.put("reviews",dao.query("SELECT r.rating,r.comment,u.name reviewername FROM reviews r JOIN users u ON u.id=r.user_id WHERE r.product_id=? ORDER BY r.created_at DESC",id));send(s,200,x);return;}if(p.equals("/auth/me")){Map<String,Object>u=user(q);if(u==null)throw new Nope();send(s,200,u);return;}if(p.equals("/cart")){send(s,200,dao.query("SELECT c.product_id productid,c.quantity,p.name,p.price,p.category,p.image_url imageurl FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.user_id=?",uid(q)));return;}if(p.equals("/orders")){send(s,200,dao.query("SELECT o.* FROM orders o WHERE o.buyer_id=? ORDER BY o.created_at DESC",uid(q)));return;}if(p.equals("/seller/products")){Map<String,Object>u=need(q,"SELLER");send(s,200,dao.query("SELECT * FROM products WHERE seller_id=? ORDER BY created_at DESC",u.get("id")));return;}if(p.equals("/seller/orders")){Map<String,Object>u=need(q,"SELLER");send(s,200,dao.query("SELECT DISTINCT o.*,u.name buyername FROM orders o JOIN order_items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id JOIN users u ON u.id=o.buyer_id WHERE p.seller_id=? ORDER BY o.created_at DESC",u.get("id")));return;}if(p.equals("/admin")){need(q,"ADMIN");send(s,200,Map.of("users",dao.query("SELECT id,name,email,role,created_at FROM users ORDER BY created_at DESC"),"orders",dao.query("SELECT o.*,u.name buyername FROM orders o JOIN users u ON u.id=o.buyer_id ORDER BY o.created_at DESC")));return;}if(p.equals("/health")){dao.query("SELECT 1");send(s,200,Map.of("status","UP","db","UP"));return;}throw new Missing();}catch(Exception e){fail(s,e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{String p=q.getPathInfo();try{Map<String,Object>b=body(q);if("/auth/register".equals(p)){String name=str(b,"name"),email=str(b,"email").toLowerCase(Locale.ROOT),pw=str(b,"password"),role=str(b,"role");if(name.isBlank()||!email.matches("^[^@\s]+@[^@\s]+\.[^@\s]+$")||pw.length()<8||!List.of("BUYER","SELLER").contains(role))throw new Bad("Enter a name, valid email, password with 8+ characters, and buyer or seller role.");long id=dao.insert("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)",name,email,BCrypt.hashpw(pw,BCrypt.gensalt(12)),role);Map<String,Object>u=Map.of("id",id,"name",name,"email",email,"role",role);q.getSession(true);q.changeSessionId();q.getSession(true).setAttribute("user",u);send(s,201,u);return;}if("/auth/login".equals(p)){String email=str(b,"email").toLowerCase(Locale.ROOT);List<Map<String,Object>>a=dao.query("SELECT id,name,email,password_hash,role FROM users WHERE email=?",email);if(a.isEmpty()||!BCrypt.checkpw(str(b,"password"),String.valueOf(a.get(0).get("password_hash"))))throw new Nope();Map<String,Object>x=a.get(0),u=Map.of("id",x.get("id"),"name",x.get("name"),"email",x.get("email"),"role",x.get("role"));if(q.getSession(false)!=null)q.getSession(false).invalidate();q.changeSessionId();q.getSession(true).setAttribute("user",u);send(s,200,u);return;}if("/auth/logout".equals(p)){if(q.getSession(false)!=null)q.getSession(false).invalidate();send(s,200,Map.of("loggedOut",true));return;}if("/cart".equals(p)){Map<String,Object>u=need(q,"BUYER");long pid=number(b.get("productId"));int qty=(int)number(b.getOrDefault("quantity",1));if(qty<1||qty>20)throw new Bad("Quantity must be between 1 and 20.");dao.update("MERGE INTO cart_items(user_id,product_id,quantity) KEY(user_id,product_id) VALUES(?,?,COALESCE((SELECT quantity FROM cart_items WHERE user_id=? AND product_id=?),0)+?)",u.get("id"),pid,u.get("id"),pid,qty);send(s,201,Map.of("added",true));return;}if("/orders".equals(p)){try{send(s,201,orderService.placeOrder(uid(q)));}catch(IllegalArgumentException invalidOrder){throw new Bad(invalidOrder.getMessage());}return;}if("/seller/products".equals(p)){Map<String,Object>u=need(q,"SELLER");String name=str(b,"name"),cat=str(b,"category");if(name.isBlank()||!List.of("Fashion","Accessories","Tech").contains(cat))throw new Bad("Product name and a valid category are required.");BigDecimal price=new BigDecimal(String.valueOf(b.get("price")));int stock=(int)number(b.get("stockQty"));if(price.signum()<=0||stock<0)throw new Bad("Price and stock must be positive.");long id=dao.insert("INSERT INTO products(seller_id,name,description,price,stock_qty,category,image_url) VALUES(?,?,?,?,?,?,?)",u.get("id"),name,str(b,"description"),price,stock,cat,str(b,"imageUrl"));send(s,201,Map.of("id",id));return;}if("/reviews".equals(p)){long u=uid(q),order=number(b.get("orderId")),product=number(b.get("productId")),rating=number(b.get("rating"));if(rating<1||rating>5||str(b,"comment").isBlank())throw new Bad("Add a 1 to 5 star rating and a little comment.");if(dao.query("SELECT i.id FROM order_items i JOIN orders o ON o.id=i.order_id WHERE o.id=? AND o.buyer_id=? AND i.product_id=? AND o.status IN ('CONFIRMED','SHIPPED','DELIVERED')",order,u,product).isEmpty())throw new Forbidden();dao.update("MERGE INTO reviews(product_id,user_id,rating,comment) KEY(product_id,user_id) VALUES(?,?,?,?)",product,u,rating,str(b,"comment"));send(s,201,Map.of("saved",true));return;}if(p!=null&&p.matches("/wishlist/[0-9]+")){long u=need(q,"BUYER").get("id") instanceof Number n?n.longValue():0,pid=Long.parseLong(p.substring(10));dao.update("MERGE INTO wishlist(user_id,product_id) KEY(user_id,product_id) VALUES(?,?)",u,pid);send(s,201,Map.of("saved",true));return;}if("/chat".equals(p)){String m=str(b,"message");if(m.isBlank()||m.length()>500)throw new Bad("Keep your message under 500 characters.");HttpSession session=q.getSession();String cacheKey=m.toLowerCase(Locale.ROOT);Map<String,String> cache=(Map<String,String>)session.getAttribute("chatCache");Integer count=(Integer)session.getAttribute("chatCount");long since=(Long)Optional.ofNullable((Long)session.getAttribute("chatSince")).orElse(System.currentTimeMillis());if(System.currentTimeMillis()-since>60000){since=System.currentTimeMillis();count=0;}if(count!=null&&count>=10)throw new Bad("A tiny pause, please — try chatting again in a minute.");session.setAttribute("chatSince",since);session.setAttribute("chatCount",count==null?1:count+1);if(cache!=null&&cache.containsKey(cacheKey)){send(s,200,Map.of("reply",cache.get(cacheKey)));return;}String reply;try{reply=chatProvider.getReply(m,"SnehaMart product listings, sizing, accessories, shipping, returns and mock checkout FAQs");}catch(Exception providerFailure){reply="I had a little hiccup. Try again in a moment, lovely ♡";}if(cache==null)cache=new HashMap<>();cache.put(cacheKey,reply);session.setAttribute("chatCache",cache);send(s,200,Map.of("reply",reply));return;}throw new Missing();}catch(Exception e){fail(s,e);}}
 protected void doPut(HttpServletRequest q,HttpServletResponse s)throws IOException{String p=q.getPathInfo();try{Map<String,Object>b=body(q);if(p!=null&&p.matches("/cart/[0-9]+")){int qty=(int)number(b.get("quantity"));if(qty<1||qty>20)throw new Bad("Quantity must be between 1 and 20.");int n=dao.update("UPDATE cart_items SET quantity=? WHERE user_id=? AND product_id=?",qty,uid(q),Long.parseLong(p.substring(6)));if(n==0)throw new Missing();send(s,200,Map.of("updated",true));return;}if(p!=null&&p.matches("/seller/products/[0-9]+")){Map<String,Object>u=need(q,"SELLER");String name=str(b,"name"),cat=str(b,"category");BigDecimal price=new BigDecimal(String.valueOf(b.get("price")));int stock=(int)number(b.get("stockQty"));if(name.isBlank()||price.signum()<=0||stock<0||!List.of("Fashion","Accessories","Tech").contains(cat))throw new Bad("Check product name, category, price and stock.");int n=dao.update("UPDATE products SET name=?,description=?,price=?,stock_qty=?,category=?,image_url=? WHERE id=? AND seller_id=?",name,str(b,"description"),price,stock,cat,str(b,"imageUrl"),Long.parseLong(p.substring(17)),u.get("id"));if(n==0)throw new Missing();send(s,200,Map.of("updated",true));return;}throw new Missing();}catch(Exception e){fail(s,e);}}
 protected void doDelete(HttpServletRequest q,HttpServletResponse s)throws IOException{String p=q.getPathInfo();try{if(p!=null&&p.matches("/cart/[0-9]+")){dao.update("DELETE FROM cart_items WHERE user_id=? AND product_id=?",uid(q),Long.parseLong(p.substring(6)));send(s,200,Map.of("removed",true));return;}if(p!=null&&p.matches("/seller/products/[0-9]+")){Map<String,Object>u=need(q,"SELLER");int n=dao.update("UPDATE products SET active=FALSE WHERE id=? AND seller_id=?",Long.parseLong(p.substring(17)),u.get("id"));if(n==0)throw new Missing();send(s,200,Map.of("removed",true));return;}if(p!=null&&p.matches("/admin/products/[0-9]+")){need(q,"ADMIN");int n=dao.update("UPDATE products SET active=FALSE WHERE id=?",Long.parseLong(p.substring(16)));if(n==0)throw new Missing();send(s,200,Map.of("removed",true));return;}throw new Missing();}catch(Exception e){fail(s,e);}}
 private void fail(HttpServletResponse s,Exception e)throws IOException{if(e instanceof Nope){send(s,401,"Please sign in first.");return;}if(e instanceof Forbidden){send(s,403,"You don't have access to that little corner.");return;}if(e instanceof Missing){send(s,404,"That little thing could not be found.");return;}if(e instanceof Bad){send(s,400,e.getMessage());return;}getServletContext().log("SnehaMart API request failed",e);send(s,500,"Something went wrong. Please try again.");}private static class Nope extends RuntimeException{}private static class Forbidden extends RuntimeException{}private static class Missing extends RuntimeException{}private static class Bad extends RuntimeException{Bad(String m){super(m);}}
}